package com.mockarena.evaluation.config;
import com.fasterxml.jackson.databind.ObjectMapper; import com.mockarena.evaluation.security.EvaluationWorkloadTokenFilter; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class EvaluationSecurityConfiguration {
 @Bean @ConditionalOnProperty(prefix="evaluation.security",name="enabled",havingValue="true",matchIfMissing=true) SecurityFilterChain secured(HttpSecurity http,ObjectMapper json,@Value("${evaluation.workload-auth.incoming-token:}")String incoming,@Value("${evaluation.workload-auth.assessment-snapshot-token:}")String assessment,@Value("${evaluation.workload-auth.question-coding-token:}")String question)throws Exception{if(blank(incoming)||blank(assessment)||blank(question))throw new IllegalStateException("Evaluation workload credentials are required when security is enabled");return http.csrf(c->c.disable()).addFilterBefore(new EvaluationWorkloadTokenFilter(incoming,json),org.springframework.security.web.authentication.AnonymousAuthenticationFilter.class).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/internal/**").permitAll().anyRequest().denyAll()).build();}
 @Bean @ConditionalOnProperty(prefix="evaluation.security",name="enabled",havingValue="false") SecurityFilterChain unsecured(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.anyRequest().permitAll()).build();}
 private static boolean blank(String s){return s==null||s.isBlank();}
}
